function callDllMain(exports, loadAddr, dllMain, log, options = {}) {
  const gate = requireDllCallbackGate(exports);
  try { return callDllMainOwned(exports, loadAddr, dllMain, log, options); } finally { gate.release(); }
}

async function callDllMainAsync(exports, loadAddr, dllMain, log, options = {}) {
  const gate = await acquireDllCallbackGate(exports);
  try { return await callDllMainAsyncOwned(exports, loadAddr, dllMain, log, options); } finally { gate.release(); }
}

function loadDlls(exports, memory, exeBytes, dlls, log, options = {}) {
  const gate = requireDllCallbackGate(exports);
  try { return loadDllsOwned(exports, memory, exeBytes, dlls, log, options); } finally { gate.release(); }
}
